import{_ as o,C as s,o as t,c as n,a2 as a,b as l,w as i,a as d,E as c,a3 as h}from"./chunks/framework.Dd_iHz3e.js";const w=JSON.parse('{"title":"14.1 Requirements & Capacity Estimation","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.1-requirements-and-estimation.md","filePath":"system-design/14.1-requirements-and-estimation.md"}'),m={name:"system-design/14.1-requirements-and-estimation.md"};function u(g,e,p,f,b,k){const r=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="_14-1-requirements-capacity-estimation" tabindex="-1">14.1 Requirements &amp; Capacity Estimation <a class="header-anchor" href="#_14-1-requirements-capacity-estimation" aria-label="Permalink to &quot;14.1 Requirements &amp; Capacity Estimation&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>Capacity estimation determines how much compute, memory, database storage, network bandwidth, and AI API budget a software system requires based on projected user traffic and data volume.</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li><strong>Functional Requirements</strong>: <ol><li>Ingest optical hazard frames from smart range hood cameras and detect smoke/flame conditions.</li><li>Provide zero-friction Magic Link authentication without passwords.</li><li>Stream 60-second recipe video reels with interactive ingredients drawers.</li><li>Stream generative recipe suggestions and structured recipe extraction using Gemini 3 Flash.</li><li>Run client-side multi-timers and dynamic portion calculators.</li></ol></li><li><strong>Non-Functional Requirements</strong>: <ol><li><strong>Latency</strong>: Sub-250ms time-to-first-token for AI chat; sub-50ms hazard ingestion response.</li><li><strong>Availability</strong>: 99.9% uptime for hazard ingestion endpoints.</li><li><strong>Data Durability</strong>: Zero data loss for security incident logs (<code>SafetyLog</code>).</li></ol></li></ul><hr><h2 id="_3-capacity-estimation-mathematical-arithmetic" tabindex="-1">3. Capacity Estimation &amp; Mathematical Arithmetic <a class="header-anchor" href="#_3-capacity-estimation-mathematical-arithmetic" aria-label="Permalink to &quot;3. Capacity Estimation &amp; Mathematical Arithmetic&quot;">​</a></h2>',8)),(t(),l(h,null,{default:i(()=>[c(r,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20ActiveCooks%5B%2210%2C000%20Active%20Kitchens%22%5D%20--%3E%20VisionTelemetry%5B%22Telemetry%3A%202%2C000%20req%2Fsec%20(1.2%20MB%2Fs)%22%5D%0A%20%20%20%20ActiveCooks%20--%3E%20ReelStreams%5B%22Video%20Reels%3A%201%2C000%20streams%20(1.5%20Gbps)%22%5D%0A%20%20%20%20ActiveCooks%20--%3E%20AIQueries%5B%22AI%20Queries%3A%2020%20req%2Fsec%20(16%2C000%20tokens%2Fsec)%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="arithmetic-breakdown-target-10-000-concurrent-active-kitchens" tabindex="-1">Arithmetic Breakdown (Target: 10,000 Concurrent Active Kitchens) <a class="header-anchor" href="#arithmetic-breakdown-target-10-000-concurrent-active-kitchens" aria-label="Permalink to &quot;Arithmetic Breakdown (Target: 10,000 Concurrent Active Kitchens)&quot;">​</a></h3><ol><li><strong>Vision Ingestion Throughput</strong>: <ul><li>Each active kitchen camera samples 1 frame every 5 seconds = $0.2 \\text{ requests/sec/kitchen}$.</li><li>For 10,000 concurrent kitchens: $10,000 \\times 0.2 = \\mathbf{2,000 \\text{ requests/sec}}$ peak write load to <code>/api/vision</code>.</li><li>Payload size per telemetry ping: ~600 bytes JSON.</li><li>Bandwidth Ingress: $2,000 \\times 600 \\text{ B} = \\mathbf{1.2 \\text{ MB/sec}} \\approx 9.6 \\text{ Mbps}$.</li></ul></li><li><strong>Database Storage Growth</strong>: <ul><li>Each safety log document in MongoDB: ~200 bytes BSON.</li><li>If 1% of frames flag warnings: $2,000 \\times 0.01 = 20 \\text{ writes/sec}$.</li><li>Daily storage: $20 \\times 86,400 \\times 200 \\text{ B} \\approx \\mathbf{345 \\text{ MB/day}} \\approx 10.3 \\text{ GB/month}$.</li></ul></li><li><strong>Culinary Video Reels Bandwidth</strong>: <ul><li>10% of users actively watching reels at any moment = 1,000 concurrent video streams.</li><li>Bitrate for 1080p vertical video: 1.5 Mbps.</li><li>Total Egress Bandwidth: $1,000 \\times 1.5 \\text{ Mbps} = \\mathbf{1.5 \\text{ Gbps}}$.</li></ul></li><li><strong>AI Token Volume &amp; Cloud Cost</strong>: <ul><li>20 AI chat queries per second across active cooks.</li><li>Average interaction: 400 input tokens + 600 output tokens = 1,000 tokens/query.</li><li>Token throughput: $20 \\times 1,000 = \\mathbf{20,000 \\text{ tokens/sec}}$.</li><li>Daily tokens: $20,000 \\times 3,600 \\times 4 \\text{ peak hours} \\approx 288 \\text{M tokens/day}$.</li><li>Monthly AI Budget (Gemini 3 Flash at ~$0.15/M blended): $\\approx \\mathbf{$1,296/month}$.</li></ul></li></ol><hr><h2 id="_4-alternatives-matrix" tabindex="-1">4. Alternatives Matrix <a class="header-anchor" href="#_4-alternatives-matrix" aria-label="Permalink to &quot;4. Alternatives Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scaling Tier</th><th>Active Users</th><th>Vision RPS</th><th>Video Egress</th><th>Database Size</th><th>AI Cost / Mo</th></tr></thead><tbody><tr><td><strong>Current Scale (MVP)</strong></td><td>100</td><td>20 RPS</td><td>15 Mbps</td><td>100 MB/mo</td><td>~$15</td></tr><tr><td><strong>10x Scale</strong></td><td>1,000</td><td>200 RPS</td><td>150 Mbps</td><td>1 GB/mo</td><td>~$130</td></tr><tr><td><strong>100x Scale</strong></td><td>10,000</td><td>2,000 RPS</td><td>1.5 Gbps</td><td>10.3 GB/mo</td><td>~$1,300</td></tr><tr><td><strong>1000x Scale (Global)</strong></td><td>100,000</td><td>20,000 RPS</td><td>15 Gbps</td><td>103 GB/mo</td><td>~$13,000</td></tr></tbody></table><hr><h2 id="_5-trade-offs-accepted" tabindex="-1">5. Trade-offs Accepted <a class="header-anchor" href="#_5-trade-offs-accepted" aria-label="Permalink to &quot;5. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>Edge Metadata vs Raw Video</strong>: We choose to process camera frames on local range hood hardware and send only JSON metadata over the internet, trading away cloud raw video recording in exchange for 99% bandwidth reduction and total privacy protection.</li></ul><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: Direct MongoDB write connections from Express will cause connection pool exhaustion during peak dinner hours.</li><li><strong>At 100x</strong>: Serving video reels from a single cloud origin saturates server network cards.</li><li><strong>At 1,000x</strong>: Gemini API global concurrency quotas will throttle users without a multi-region provider fallback mesh.</li></ul><hr><h2 id="_7-senior-engineer-improvements" tabindex="-1">7. Senior Engineer Improvements <a class="header-anchor" href="#_7-senior-engineer-improvements" aria-label="Permalink to &quot;7. Senior Engineer Improvements&quot;">​</a></h2><p>Introduce a dedicated <strong>Message Ingestion Buffer</strong> (Kafka or AWS SQS) in front of the database. The <code>/api/vision</code> endpoint writes directly to the buffer and immediately responds with HTTP 202, while worker nodes batch-write records to MongoDB in chunks of 500 documents.</p><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;For capacity estimation on Cooking Nexus, our biggest engineering driver is supporting 10,000 concurrent kitchens. With range cameras sending safety telemetry every five seconds, that&#39;s 2,000 requests per second at 1.2 megabytes of ingress. By processing raw optical frames on local device hardware and only transmitting JSON hazard alerts, we keep our database writes down to 20 operations per second and under 11 gigabytes of monthly storage growth, while offloading 1.5 gigabits of video reel traffic to global edge CDNs.&quot;</p>',17))])}const y=o(m,[["render",u]]);export{w as __pageData,y as default};
